module CsilCbor
  module_function

  class RpErrorRefusal < StandardError
    attr_reader :value

    def initialize(value)
      @value = value
      super("RpError")
    end
  end

  def encode_rp_sign_request_reply
    value = yield
    ["RpSignResponse", encode((value).csil_to_tree)]
  rescue RpErrorRefusal => refusal
    ["RpError", encode((refusal.value).csil_to_tree)]
  end

  def encode_rp_decrypt_token_reply
    value = yield
    ["RpDecryptResponse", encode((value).csil_to_tree)]
  rescue RpErrorRefusal => refusal
    ["RpError", encode((refusal.value).csil_to_tree)]
  end

  def encode_rp_verify_assertion_reply
    value = yield
    ["RpVerifyResponse", encode((value).csil_to_tree)]
  rescue RpErrorRefusal => refusal
    ["RpError", encode((refusal.value).csil_to_tree)]
  end

  def encode_rp_userinfo_fetch_reply
    value = yield
    ["UserInfo", encode((value).csil_to_tree)]
  rescue RpErrorRefusal => refusal
    ["RpError", encode((refusal.value).csil_to_tree)]
  end

  def resolve_rpc_reply(service, op, variant, payload)
    if service == "Rp" && op == "sign-request"
      case variant
      when "RpSignResponse" then return payload
      when "RpError" then raise RpErrorRefusal.new(RpError.csil_from_tree(decode(payload)))
      else raise ArgumentError, "invalid RPC reply variant: #{variant.inspect}"
      end
    end
    if service == "Rp" && op == "decrypt-token"
      case variant
      when "RpDecryptResponse" then return payload
      when "RpError" then raise RpErrorRefusal.new(RpError.csil_from_tree(decode(payload)))
      else raise ArgumentError, "invalid RPC reply variant: #{variant.inspect}"
      end
    end
    if service == "Rp" && op == "verify-assertion"
      case variant
      when "RpVerifyResponse" then return payload
      when "RpError" then raise RpErrorRefusal.new(RpError.csil_from_tree(decode(payload)))
      else raise ArgumentError, "invalid RPC reply variant: #{variant.inspect}"
      end
    end
    if service == "Rp" && op == "userinfo-fetch"
      case variant
      when "UserInfo" then return payload
      when "RpError" then raise RpErrorRefusal.new(RpError.csil_from_tree(decode(payload)))
      else raise ArgumentError, "invalid RPC reply variant: #{variant.inspect}"
      end
    end
    payload
  end
end
